//! A FrameSet's Current attribute is set, cleared and written as C's is:
//! unset until a Frame is added or Current is set, written commented out
//! while unset, cleared when the current Frame is removed, and renumbered
//! when an earlier Frame is.
//!
//! `frameset_current_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/frameset_current_probe.c`.

use crate::common::native_dump;
#[path = "frameset_current_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrameBuilder, Frame, FrameRef, FrameSet};
use starlink_ast::mappings::UnitMap;
use starlink_ast::{AnyObject, from_native_string};

fn frame(i: usize) -> Box<dyn Frame> {
    let mut f = BasicFrameBuilder::new(1).build().unwrap();
    Frame::set_domain(&mut f, &format!("F{i}")).unwrap();
    Box::new(f)
}

/// A FrameSet of `n` one-axis Frames, as the probe builds it.
fn frameset(n: usize) -> FrameSet {
    let mut fs = FrameSet::new(frame(1));
    for i in 2..=n {
        fs.add_frame(FrameRef::Base, Box::new(UnitMap::new(1)), frame(i))
            .unwrap();
    }
    fs
}

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

#[test]
fn current_follows_the_c_library() {
    let mut got: Vec<(&str, FrameSet)> = Vec::new();
    got.push(("one_frame", frameset(1)));

    let mut fs = frameset(3);
    got.push(("three_frames", fs.clone()));
    fs.clear_current();
    got.push(("three_cleared", fs.clone()));
    fs.remove_frame(FrameRef::Index(1)).unwrap();
    got.push(("cleared_remove_first", fs));

    let mut fs = frameset(3);
    fs.remove_frame(FrameRef::Index(1)).unwrap();
    got.push(("set_remove_first", fs.clone()));
    fs.remove_frame(FrameRef::Index(2)).unwrap();
    got.push(("set_remove_current", fs));

    let mut fs = frameset(3);
    fs.set_current(FrameRef::Index(1)).unwrap();
    fs.remove_frame(FrameRef::Index(3)).unwrap();
    got.push(("set_first_remove_last", fs));

    let names: Vec<&str> = got.iter().map(|g| g.0).collect();
    let want_names: Vec<&str> = cases::STEPS.iter().map(|s| s.0).collect();
    assert_eq!(names, want_names, "the test runs the probe's steps");

    let mut failures = Vec::new();
    for ((name, fs), &(_, set, dump)) in got.into_iter().zip(cases::STEPS) {
        if fs.test_current() != set {
            failures.push(format!("{name}: test_current is {}, C gives {set}", !set));
        }
        let written = native_dump(&AnyObject::FrameSet(fs)).unwrap();
        if written != text(dump) {
            failures.push(format!(
                "{name}: dump differs\n{written}\nC:\n{}",
                text(dump)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Each dump reads back with Current set or unset as C wrote it, and
/// writes out unchanged.
#[test]
fn current_reads_back_as_written() {
    for &(name, set, dump) in cases::STEPS {
        let AnyObject::FrameSet(fs) = from_native_string(&text(dump)).unwrap() else {
            panic!("{name}: not a FrameSet");
        };
        assert_eq!(fs.test_current(), set, "{name}");
        let written = native_dump(&AnyObject::FrameSet(fs)).unwrap();
        assert_eq!(written, text(dump), "{name}");
    }
}
